    "t1_i5": "Apfel",
    "t1_i6": "Karpaten",
    "t2_title": "Der bestimmte und unbestimmte Artikel",
    "t2_text": "Wir verknüpfen den Artikel mit dem Nomen und prüfen, ob sich die Aussage auf eine bekannte oder eine undefinierte Sache bezieht.",
    "t2_inst": "Ordnen Sie die Form der richtigen Gruppe zu.",
    "t2_h1": "Der unbestimmte Artikel zeigt nichts Bestimmtes.",
    "t2_h2": "Der bestimmte Artikel trägt einen bekannten Namen.",
    "t2_q": "Was ist die dezidiert artikulierte Form?",
