    "t3_text": "Wir verwenden Pronomen, um die Wiederholung von Namen zu vermeiden und sie der richtigen Person zuzuordnen.",
    "t3_inst": "Gruppenpronomen nach Person.",
    "t3_h1": "Die erste Person spricht über sich.",
    "t3_h2": "Die dritte Person spricht über jemand anderen.",
