    "t4_title": "Die Zahl",
    "t4_text": "Wir trennen die Kardinalzahlen von den Ordinalzahlen und sehen, wie die Position in der Zeichenfolge aussieht.",
    "t4_inst": "Ordne die Zahlen der richtigen Gruppe zu.",
    "t4_h1": "Kardinäle sagen, wie viele es sind.",
    "t4_h2": "Ordinalzahlen geben die Stelle in der Zeichenfolge an.",
