    "t5_title": "das Adjektiv",
    "t5_text": "Wir finden die Wörter, die Eigenschaften aufweisen und erkennen sie in der Äußerung.",
    "t5_inst": "Berühren Sie die Wörter, die Adjektiv sind.",
    "t5_h1": "Das Adjektiv zeigt eine Eigenschaft.",
    "t5_h2": "Es steht normalerweise neben einem Nomen.",
