    "t6_title": "Nomen Kasus (N/Ac)",
    "t6_text": "Das Nomen ändert seine Form und Rolle. Der Nominativ ist das Subjekt, der Akkusativ die Ergänzung.",
    "t6_inst": "Gruppieren Sie die Sätze gedanklich nach dem Fall des unterstrichenen Nomen.",
    "t6_h1": "Der Nominativ antwortet wer/was.",
    "t6_h2": "Der Akkusativ antwortet auf wer/was.",
