    "t7_title": "Grundlegende syntaktische Funktionen",
    "t7_text": "Das Nomen kann Subjekt, Prädikatsnomen, Attribut oder Komplement sein.",
    "t7_inst": "Ordnen Sie die Funktion ihrer Frage oder Rolle zu.",
    "t7_h1": "Das Subjekt ist der Urheber der Aktion.",
    "t7_h2": "Das Attribut bestimmt ein Nomen.",
    "t7_q": "Welche Funktion beantwortet die Frage „Welche?“",
