    "t7_r3": "WHO? Was?",
    "t7_l4": "Prädikatives Nomen",
    "t7_r4": "bilden das Nominalprädikat",
    "t8_title": "Vergleichsgrade",
    "t8_text": "Das Adjektiv kann die Intensität der Aneignung durch Vergleichsgrade zeigen.",
    "t8_inst": "Setze das Adjektiv im richtigen Grad ein.",
    "t8_h1": "Das Positive ist die einfache Form.",
    "t8_h2": "Der Komparativ vergleicht, der Superlativ ist das Maximum.",
