    "t9_title": "Reflexivpronomen",
    "t9_text": "Das Reflexivpronomen zeigt, dass die Handlung zum Subjekt zurückkehrt.",
    "t9_inst": "Wählen Sie das passende Reflexivpronomen.",
    "t9_h1": "Die Handlung wird von derselben Person ausgeführt und erlitten.",
