    "t10_title": "Bruchzahl und multiplikative Zahl",
    "t10_text": "Manche Zahlen geben Teile eines Ganzen an oder wie oft sich eine Menge erhöht.",
    "t10_inst": "Gruppieren Sie die Ziffern.",
