    "t1_i1": "child",
    "t1_i2": "Ana",
    "t1_i3": "city",
    "t1_i4": "Bucharest",
    "t1_i5": "apple",
    "t1_i6": "Carpathians",
    "t2_title": "The definite and indefinite article",
    "t2_text": "We link the article to the noun and see if the statement is talking about a known thing or an undefined thing.",
    "t2_inst": "Put the shape in the correct group.",
    "t2_h1": "The indefinite article does not show something specific.",
    "t2_h2": "The definite article shows a familiar name.",
    "t2_q": "What is the decidedly articulated form?",
    "t2_qa": "one",
    "t2_qb": "o",
    "t2_qc": "the child",
    "t2_qd": "some",
    "t2_b1": "undecided",
    "t2_b2": "determined",
    "t2_i1": "a child",
    "t2_i2": "a book",
    "t2_i3": "the child",
    "t2_i4": "the book",
    "t3_title": "Personal pronouns",
    "t3_text": "We use pronouns to avoid repeating names and link them to the right person.",
    "t3_inst": "Group pronouns by person.",
    "t3_h1": "First person is talking about himself.",
    "t3_h2": "The third person is talking about someone else.",
    "t3_q": "What pronoun is in the third person?",
    "t3_qa": "me",
    "t3_qb": "you",
    "t3_qc": "he",
    "t3_qd": "us",
    "t3_b1": "first person",
    "t3_b2": "second person",
    "t3_b3": "third person",
    "t3_i1": "me",
    "t3_i2": "us",
    "t3_i3": "you",
    "t3_i4": "you",
    "t3_i5": "he",
    "t3_i6": "her",
    "t4_title": "The numeral",
    "t4_text": "We separate the cardinal numerals from the ordinal ones and see what the position in the string looks like.",
    "t4_inst": "Put the numbers in the correct group.",
    "t4_h1": "Cardinals say how many there are.",
    "t4_h2": "Ordinals tell the place in the string.",
    "t4_q": "What is ordinal number?",
    "t4_qa": "two",
    "t4_qb": "six",
    "t4_qc": "the second",
    "t4_qd": "four",
    "t4_b1": "cardinal",
    "t4_b2": "ordinal",
    "t4_i1": "two",
