    "t4_i3": "the second",
    "t4_i4": "first",
    "t4_i5": "six",
    "t4_i6": "the fourth",
    "t5_title": "the adjective",
    "t5_text": "We find the words that show attributes and recognize them in the utterance.",
    "t5_inst": "Touch the words that are adjectives.",
    "t5_h1": "The adjective shows a property.",
    "t5_h2": "It usually stands next to a noun.",
    "t5_q": "Which word is an adjective?",
    "t5_qa": "nice",
    "t5_qb": "run",
    "t5_qc": "table",
    "t5_qd": "child",
    "t5_w1": "The child",
    "t5_w2": "happy",
    "t5_w3": "and",
    "t5_w4": "industrious",
    "t5_w5": "read",
    "t5_w6": "daily",
    "t6_title": "Noun Case (N/Ac)",
    "t6_text": "The noun changes its form and role. The nominative is the subject, the accusative is the complement.",
    "t6_inst": "Group the sentences according to the case of the underlined noun mentally.",
    "t6_h1": "The nominative answers who/what.",
    "t6_h2": "The accusative answers to who/what.",
    "t6_q": "In which case is 'the book' in 'I'm reading the book'?",
    "t6_qa": "Nominative",
    "t6_qb": "Accusative",
    "t6_qc": "dative",
    "t6_qd": "Genitive",
