    "t6_i2": "I see a boy.",
    "t6_i3": "The book is new.",
    "t6_i4": "I am reading a book.",
    "t7_title": "Basic syntactic functions",
    "t7_text": "The noun can be subject, predicate noun, attribute or complement.",
    "t7_inst": "Match the function to its question or role.",
    "t7_h1": "The subject is the author of the action.",
    "t7_h2": "The attribute determines a noun.",
    "t7_q": "Which function answers the question 'which?'",
    "t7_qa": "Subject",
    "t7_qb": "Attribute",
    "t7_qc": "Complement",
    "t7_qd": "Predicated",
    "t7_l1": "Subject",
