    "t7_r4": "form the nominal predicate",
    "t8_title": "Degrees of comparison",
    "t8_text": "The adjective can show the intensity of the appropriation through degrees of comparison.",
    "t8_inst": "Put the adjective in the right degree.",
    "t8_h1": "The positive is the simple form.",
    "t8_h2": "The comparative compares, the superlative is the maximum.",
    "t8_q": "To what degree is 'very nice'?",
    "t8_qa": "Positive",
    "t8_qb": "Comparatively",
    "t8_qc": "Relative superlative",
    "t8_qd": "Absolute superlative",
