    "t8_i3": "very good",
    "t8_i4": "the best",
    "t9_title": "Reflexive pronoun",
    "t9_text": "The reflexive pronoun shows that the action returns to the subject.",
    "t9_inst": "Choose the appropriate reflexive pronoun.",
    "t9_h1": "The action is done and suffered by the same person.",
    "t9_h2": "We use 'se' for the third person.",
    "t9_q": "What is a reflexive pronoun?",
    "t9_qa": "me",
    "t9_qb": "on him",
    "t9_qc": "his",
    "t9_qd": "their",
    "t9_s": "The child ___ washes his hands.",
