    "explorer_title": "Das Verb – Stimmungen und Zeiten",
    "t1_title": "Infinitiv- und Personalform",
    "t1_text": "Wir gehen von der Wörterbuchform des Verbs aus und unterscheiden es von Formen, die sich je nach Person und Numerus ändern.",
