    "t4_c2": "olvastam",
    "t4_c3": "olvasni fogok",
    "t4_c4": "olvasni",
    "t5_title": "Ige megegyezés",
    "t5_text": "Az ige személyét és számát egyeztetjük a mondatban szereplő alanyal.",
    "t5_inst": "Érintse meg azokat az igéket, amelyek helyesen egyeznek a témával.",
    "t5_h1": "A \"mi\" alanyhoz többes számú ige szükséges.",
    "t5_h2": "Az igéknek többes szám első személyben kell szerepelniük.",
    "t5_q": "Melyik forma helyes az „ők” témával?",
