    "t5_w6": "tiszta",
    "t6_title": "Jelző hangulat (összetett igeidők)",
    "t6_text": "A jelzőben vannak segédigéket tartalmazó összetett igeidők.",
    "t6_inst": "Csoportosítsa az igéket idő szerint!",
    "t6_h1": "A tökéletes vegyület az „am, ai, a” kifejezéseket használja.",
    "t6_h2": "A jövő az „akarat, akarat, akarat” kifejezést használja.",
    "t6_q": "Hány óra az „elmentem”?",
    "t6_qa": "Jelen",
    "t6_qb": "Tökéletesen megkomponált",
