    "t6_qd": "Jövő",
    "t6_b1": "Tökéletesen megkomponált",
    "t6_b2": "Több mint tökéletes",
    "t6_b3": "Jövő",
    "t6_i1": "olvastam",
    "t6_i2": "olvastam",
    "t6_i3": "olvasni fogok",
    "t7_title": "Felszólító mód",
    "t7_text": "Az imperatívusz parancsot, felszólítást vagy kérést fejez ki.",
    "t7_inst": "Üsse be a felszólító igéket.",
    "t7_h1": "Az imperatívusz a megrendeléseknél használatos.",
    "t7_h2": "Gyakran van rajta felkiáltójel.",
    "t7_q": "Mit fejez ki a felszólító hangulat?",
    "t7_qa": "Biztonságos akció",
    "t7_qb": "Parancs vagy felszólítás",
    "t7_qc": "Egy kívánság",
    "t7_qd": "Egy feltétel",
    "t7_qmain": "Mely igék kötelezőek?",
    "t7_t1": "Olvas!",
    "t7_t2": "olvastam",
    "t7_t3": "Jön!",
    "t7_t4": "megyek",
    "t8_title": "Szubjunktív mód",
    "t8_text": "A kötőszó egy lehetséges, megvalósítható cselekvést fejez ki, és a „to” kötőszót használja.",
    "t8_inst": "Válassza ki a szubjunktív módra jellemző kötőszót.",
    "t8_h1": "A kötőszó az „sa”-val épül fel.",
    "t8_h2": "Vágyat vagy lehetőséget fejez ki.",
    "t8_q": "Mi az a szubjunktív hangulatjelző?",
    "t8_qa": "a",
    "t8_qb": "hogy",
