    "t8_c2": "a",
    "t8_c3": "o",
    "t8_c4": "hogy",
    "t9_title": "Feltételes-optatív mód",
    "t9_text": "Olyan cselekvést fejez ki, amely egy állapottól vagy vágytól függ.",
    "t9_inst": "Párosítsa a formát az idővel.",
    "t9_h1": "A feltételes feltétel az 'aş, ai, ar'-t használja.",
    "t9_h2": "A tökéletesnek megvan a 'be' ige is.",
    "t9_q": "Milyen hangulatú az „énekelnék”?",
