    "t9_r4": "tökéletes",
    "t10_title": "Kopulációs igék",
    "t10_text": "A 'to be' ige akkor lehet kopulatív, ha egy predikatív főnévvel együtt alkotja a névleges állítmányt.",
    "t10_inst": "Érintse meg a kopulatív igét.",
    "t10_h1": "A „to be” ige az alanyt a predikatív főnévhez köti.",
    "t10_h2": "Ennek itt önmagában nincs értelme.",
