    "t10_qc": "Amikor kisegítő",
    "t10_qd": "Amikor az infinitivusban van",
    "t10_w1": "Ő",
    "t10_w2": "ez van",
    "t10_w3": "diák",
    "t10_w4": "szorgalmas",
    "t11_title": "A személytelen hangulatok szintaktikai funkciói",
    "t11_text": "A főnévi igenév, a gerund, a melléknév és a kötőszó főnévi, melléknévi vagy határozói funkcióval rendelkezhet.",
    "t11_inst": "Csoportosítás szintaktikai függvény szerint.",
