    "t8_title": "Die umständliche Ergänzung des Ortes",
    "t8_text": "Zeigen Sie den Ort an, an dem die Aktion stattfindet, und beantworten Sie die Frage „Wo?“.",
    "t8_inst": "Berühren Sie die Wörter, die die Ortsergänzung bilden.",
