    "t15_h1": "Introducerea conține teza.",
    "t15_h2": "Cuprinsul are argumentele, încheierea are concluzia.",
    "t15_q": "Ce conține cuprinsul unui text argumentativ?",
    "t15_qa": "Teza",
    "t15_qb": "Argumentele și exemplele",
    "t15_qc": "Concluzia",
    "t15_qd": "Titlul",
    "t15_w1": "Introducere,",
    "t15_w2": "cuprins",
    "t15_w3": "și",
    "t15_w4": "încheiere."
