    "t11_text": "Ein Objekt, Wesen oder Bild, das eine abstrakte Idee darstellt.",
    "t11_inst": "Ordnen Sie das Symbol der Idee zu, die es darstellt.",
    "t11_h1": "Das Symbol hat eine kulturell anerkannte Bedeutung.",
    "t11_h2": "Es wird oft in der Poesie verwendet.",
