    "t12_title": "Das Oxymoron",
    "t12_text": "Die ungewöhnliche Verbindung zweier Wörter mit widersprüchlicher Bedeutung, die ein neues Bild entstehen lässt.",
    "t12_inst": "Berühren Sie die Wörter, die das Oxymoron bilden.",
    "t12_h1": "Stille kann logischerweise nicht ohrenbetäubend sein.",
    "t12_h2": "Der Kontrast erzeugt ein kraftvolles poetisches Bild.",
