    "t13_title": "Der metaphorische Beiname",
    "t13_text": "Ein Beiname, der gleichzeitig eine Metapher ist und ein ungewöhnliches Bild suggeriert.",
    "t13_inst": "Gruppieren Sie die Beinamen.",
    "t13_h1": "Das metaphorische Epitheton überträgt Bedeutungen zwischen verschiedenen Bereichen.",
