    "t14_text": "Eine Metapher, die einem Objekt oder Phänomen menschliche Eigenschaften zuschreibt.",
    "t14_inst": "Wählen Sie das Wort, das die personifizierende Metapher erzeugt.",
    "t14_h1": "Die Nacht wird als eine Person gesehen, die einen Umhang trägt.",
