    "t4_i2": "egyre hangosabban",
    "t4_i3": "alma, körte, szilva",
    "t4_i4": "fent, lent, mindenhol",
    "t5_title": "Metafora",
    "t5_text": "A metafora hasonlóságot sugall anélkül, hogy közvetlenül kijelentené.",
    "t5_inst": "Egészítsd ki a beszédfigura nevével.",
