    "t6_title": "Hiperbola",
    "t6_text": "Egy tárgy vagy jelenség arányainak szándékos eltúlzása a kifejezőképesség fokozása érdekében.",
    "t6_inst": "Győzd le a hiperbolát.",
    "t6_h1": "A hiperbola erősen eltúlozza a valóságot.",
