    "t6_t2": "szép mint a virág",
    "t6_t3": "– kiáltott tengernyi könny",
    "t6_t4": "a magas fa",
    "t7_title": "Az ellentét",
    "t7_text": "Két szó, ötlet vagy kép szembeállítása egymás kiemelésére.",
    "t7_inst": "Párosítsa az ellenkező kifejezéseket!",
    "t7_h1": "Az antitézis antonimákon alapul.",
