    "t10_t4": "îmbrățișată",
    "t11_title": "Tema textului",
    "t11_text": "Tema este aspectul general al realității abordat în text (ex: natura, iubirea, copilăria).",
    "t11_inst": "Așază cuvintele în ordine.",
    "t11_h1": "Tema este mai largă decât mesajul.",
    "t11_h2": "Multe texte pot avea aceeași temă.",
    "t11_q": "Ce este tema unui text literar?",
    "t11_qa": "Un personaj",
