    "t13_title": "Ritmul poeziei",
    "t13_text": "Ritmul este dat de succesiunea silabelor accentuate și neaccentuate.",
    "t13_inst": "Grupează versurile după ritm (intuitiv).",
    "t13_h1": "Ritmul trohaic este vioi, popular.",
