    "t10_t1": "gepaart",
    "t10_t2": "gekreuzt",
    "t10_t3": "Ziel",
    "t10_t4": "umarmt",
    "t11_title": "Das Thema des Textes",
    "t11_text": "Das Thema ist der allgemeine Aspekt der Realität, der im Text angesprochen wird (z. B. Natur, Liebe, Kindheit).",
    "t11_inst": "Ordne die Wörter.",
    "t11_h1": "Das Thema ist umfassender als die Botschaft.",
    "t11_h2": "Viele Texte können das gleiche Thema haben.",
    "t11_q": "Was ist das Thema eines literarischen Textes?",
    "t11_qa": "Ein Charakter",
    "t11_qb": "Der allgemeine Aspekt wird angesprochen",
    "t11_qc": "Eine Figur mit Stil",
    "t11_qd": "Eine Art der Belichtung",
    "t11_w1": "Thema",
    "t11_w2": "es ist",
    "t11_w3": "die Idee",
    "t11_w4": "allgemein",
    "t11_w5": "a",
    "t11_w6": "der Text.",
    "t12_title": "Der literarische Grund",
    "t12_text": "Ein wiederkehrendes Element, das das Thema unterstützt (z. B. der Wald, der Mond, der See).",
    "t12_inst": "Ordnen Sie das literarische Motiv dem vorgeschlagenen Thema zu.",
    "t12_h1": "Literarische Motive sind häufige Symbole.",
    "t12_h2": "Sie tragen dazu bei, die Atmosphäre zu schaffen.",
    "t12_q": "Was ist ein literarisches Motiv?",
    "t12_qa": "Ein Fehler",
    "t12_qb": "Ein wiederkehrendes Element mit symbolischem Wert",
    "t12_qc": "Eine Art Reim",
    "t12_qd": "Eine Hauptfigur",
    "t12_l1": "der Code",
    "t12_r1": "Natur",
    "t12_l2": "der Mond",
    "t12_r2": "die Nacht/der Traum",
    "t12_l3": "das Buch",
    "t12_r3": "Wissen",
    "t12_l4": "die Straße",
    "t12_r4": "die Reise/das Leben",
    "t13_title": "Der Rhythmus der Poesie",
    "t13_text": "Der Rhythmus ergibt sich aus der Abfolge betonter und unbetonter Silben.",
    "t13_inst": "Gruppieren Sie Liedtexte nach Takt (intuitiv).",
    "t13_h1": "Der trochaische Rhythmus ist lebendig und beliebt.",
    "t13_h2": "Der jambische Rhythmus ist langsamer und feierlich.",
    "t13_q": "Was gibt einem Gedicht den Rhythmus?",
    "t13_qa": "Reim",
    "t13_qb": "Abfolge betonter und unbetonter Silben",
    "t13_qc": "Die Anzahl der Strophen",
    "t13_qd": "Der Titel",
    "t13_b1": "Trochaisch",
    "t13_b2": "jambisch",
    "t13_i1": "Doi-no, doi-no, süßes Lied",
    "t13_i2": "Es ist Herbst",
    "t14_title": "Erzählperspektive",
    "t14_text": "Der Standpunkt, aus dem die Geschichte erzählt wird.",
    "t14_inst": "Tippen Sie auf die Wörter, die einen allwissenden Erzähler beschreiben.",
    "t14_h1": "Die Perspektive kann objektiv (allwissend) oder subjektiv sein.",
    "t14_h2": "Es beeinflusst, wie der Leser die Geschichte wahrnimmt.",
    "t14_q": "Wie heißt der Erzähler, der alles weiß?",
    "t14_qa": "Subjektiv",
    "t14_qb": "allwissend",
