    "t14_qd": "Zeuge",
    "t14_w1": "Der Erzähler",
    "t14_w2": "weiß",
    "t14_w3": "alles",
    "t14_w4": "ungefähr",
    "t14_w5": "Charaktere.",
    "t15_title": "Die Beziehung zwischen den Charakteren",
    "t15_text": "Die Art und Weise, wie die Charaktere interagieren, offenbart ihren Charakter und treibt die Handlung voran.",
    "t15_inst": "Wählen Sie das richtige Wort.",
    "t15_h1": "Konflikte sind der Motor der Erzählung.",
    "t15_h2": "Beziehungen können Freundschaft, Feindschaft usw. sein.",
    "t15_q": "Welche Rolle spielen Konflikte in einer Erzählung?",
