    "t1_i3": "felolvassák a színpadon",
    "t2_title": "Karakterek és akciók",
    "t2_text": "Az irodalmi szövegekben a szereplők és tetteik követik egymást.",
    "t2_inst": "Párosítsa a kifejezést a magyarázatával!",
    "t2_h1": "A karakter véletlenszerűen vesz részt.",
