    "t2_r4": "vonalak",
    "t3_title": "Lírai jelek",
    "t3_text": "A képpel és érzelmekkel ellátott szavak lírai szöveget árulnak el.",
    "t3_inst": "Érintse meg azokat a szavakat, amelyek költői képet adnak.",
    "t3_h1": "Keressen olyan szavakat, amelyek érzelmet vagy képet sugallnak.",
    "t3_h2": "A lírai szöveg kifejezőkészséget használ.",
