    "t4_title": "Az események sorrendje",
    "t4_text": "A narratívában az események világos sorrendbe kerülnek.",
    "t4_inst": "Tedd a mese lépéseit a megfelelő sorrendbe!",
    "t4_h1": "Egy eseménynek van eleje, közepe és vége.",
